fn defensive_crisis(version, rnd, player, data, target, debug) -> (bool, bool)

// --- L19 ---
tps = data.context.setting.tick_per_second            // GameSetting+0x12f8
enemy_team = 1 - player.info.team                      // PlayerState+0x930, 범위 2 밖이면 panic_bounds_check

// --- L21~26: 근접 적 챔피언 수집 ---
near_enemies: Vec<&Entity, &Bump> =
    game_cache.player_champion[enemy_team]             // AbstractGameWithCache+0x1e0, [ *Entity ; 5 ]
      .iter().filter_map(|o| o.as_ref())               // AbstractGameWithCache::iter_champions (game.rs:1904)
      .filter(|e| {                                    // ★클로저#0 = m10.ll 55868~55976 (담당 범위 밖)
          let r = plan_legacy::old::battle::max_range(e, target);              // L23
          if Entity::distance_sq(e, target) > (r + 30000)^2 { return false }   // L24 (dx,dy = abs_diff, dx*dx+dy*dy)
          if fight_model::is_ignored_well_enemy(version, player, e) { return false } // L25
              //   ↑ e.team == TeamType::Player(enemy_team) 이고
              //     path_finder::is_enemy_well_danger(version, player, e.x, e.y) 이면 true = 제외
          data.blackboard[enemy_team].is_recent_visible(game_dyn, player, e)   // L26
      })
      .collect_in(data.context.pool)

if near_enemies.len() == 0 { return (false, false) }   // L30 진입 전 조기탈출

// --- L30~35: 첫 번째 bool = die_imminent ---
tp = AbstractGameWithCache::player_by_champion_id(cache, target.id)   // L32, Entity+0x5c0
if tp == null {
    die_imminent = false                               // 소유 플레이어를 못 찾으면 사망예측 자체를 건너뛴다
} else {
    die = fight_check::check_kill_die_tick(version, rnd, data, tp, target,
                                           near_enemies.clone(), Vec::new_in(pool), debug)  // L33
    die_imminent = die < tps * 2                       // L35 (`shl tps,1`) = 2초 안에 죽는다고 예측
}
if near_enemies.len() == 0 { return (die_imminent, false) }   // 재로드 후 재확인

// --- L41~52: 두 번째 bool = CC 임박 ---
cc_imminent = near_enemies.iter().any(|e| {            // L41 클로저#1 (본문에 인라인됨)
    let is_champ = (e.ty 판별자 == 13/*Champion*/);
    let slots: [(&Option<Effect>, usize); 3] = [       // L42
        ( &e.skill_effect  /*+0x4c8, 항상*/       , if is_champ { e.skill_cooldown  } else { 0 } ),
        ( if e.level > 2 { &e.skill2_effect /*+0x500*/ } else { &NONE }, if is_champ { e.skill2_cooldown } else { 0 } ),
        ( if e.level > 4 { &e.ult_effect    /*+0x538*/ } else { &NONE }, if is_champ { e.ult_cooldown    } else { 0 } ),
    ];
    slots.iter().any(|(effect, cooldown)| {            // L47 (3칸 전부 IR 에 완전 언롤됨)
        if *cooldown > tps { return false }             //   1초 안에 쓸 수 없는 스킬은 제외
        match effect.as_ref() {                         //   Effect+0x30 == -1 이면 None → 제외
            None => false,
            Some(ef) => fight_check::effect_cc_time(version, ef).is_some(),  // L48 CC 계열 이펙트인가
        }
    })
})

return (die_imminent, cc_imminent)                     // L53

// 주의: 두 bool 은 독립이 아니다 — CC 루프에서 true 가 나오면 즉시 탈출하므로
//       그 시점의 die_imminent 값을 그대로 들고 나간다(값 자체는 위에서 확정 완료).
// 주의: rnd(&mut StdRng) 와 debug(&mut DebugFrameData) 는 이 함수가 직접 건드리지 않고
//       check_kill_die_tick 로만 흘려보낸다. 그래서 writes 가 비어 있다.
// 정리(unwind 포함): near_enemies 는 반환 직전 Vec/RawVec Drop 으로 해제된다.
